Object.assign(window.TEM8_DICTIONARY, {"squint":{"media":{"uk":"media/uk/squint__gb_1.mp3","us":"media/us/squint__us_1.mp3"},"oxford":{"phon":"skwɪnt","pos":"verb","senses":[{"en":"to look at something with your eyes partly shut in order to keep out bright light or to see better","cn":"眯着眼睛看","g":"[intransitive, transitive]","ex":{"en":"to squint into the sun","cn":"眯起眼睛看太阳"}},{"en":"to look in a different direction from the other eye","cn":"斜视","g":"[intransitive]","lab":"British English","ex":{"en":"His left eye squints a little.","cn":"他左眼有点斜视。"}},{"en":"to have eyes that look in different directions","cn":"（人）患斜视","g":"[intransitive]"},{"en":"a condition of the eye muscles which causes each eye to look in a different direction","cn":"斜视","g":"[countable, usually singular]","ex":{"en":"He was born with a squint.","cn":"他生下来就斜视。"},"pos":"noun"},{"en":"a short look","cn":"瞥；瞟","g":"[singular]","lab":"British English, informal，，","ex":{"en":"Have a squint at this.","cn":"你看看这个。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"眯着眼看","en":"If you squint at something, you look at it with your eyes partly closed.","ex":{"en":"The girl squinted at the photograph","cn":"女孩觑着眼看那张照片。"}},{"pos":"N-COUNT 可数名词","cn":"斜视(症);斗鸡眼","en":"If someone has a squint, their eyes look in different directions from each other."}]},"examples":[{"en":"When he squinted his eyes, he could just make out a house in the distance.","cn":"他眯着眼睛，只能隐约看见远处有一所房子。"},{"en":"She was squinting through the keyhole.","cn":"她眯着眼从锁眼往里看。"}]},"squat":{"media":{"uk":"media/uk/squat__gb_1.mp3","us":"media/us/squat__us_1.mp3","img":["media/ldoce/img/squat.jpg"]},"oxford":{"phon":"skwɒt","pos":"verb","senses":[{"en":"to sit on your heels with your knees bent up close to your body","cn":"蹲坐；蹲","g":"[intransitive]","ex":{"en":"Children were squatting on the floor.","cn":"孩子们蹲在地板上。"}},{"en":"to live in a building or on land which is not yours, without the owner’s permission","cn":"偷住，擅自占用（房子或地方）","g":"[intransitive, transitive]","ex":{"en":"They ended up squatting in the empty houses on Oxford Road.","cn":"他们落得在牛津路偷住空房的境地。"}},{"en":"a building that people are living in without permission and without paying rent","cn":"偷住的房子","lab":"especially British English","ex":{"en":"to live in a squat","cn":"擅自住在他人空着的房子里"},"pos":"noun"},{"en":"a squatting position of the body","cn":"蹲坐；蹲","pos":"noun"},{"en":"an exercise in which you start with your hands on the floor and your knees bent, and then quickly move both legs backwards and forwards together","cn":"俯撑下蹲促腿，俯撑腿屈伸（双手撑地下蹲后双腿同时前后跳动）","pos":"noun"},{"en":"short and wide or fat, in a way that is not attractive","cn":"矮而宽的；矮胖的","ex":{"en":"a squat tower","cn":"矮而粗的塔"},"pos":"adjective"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"蹲;蹲坐","en":"If you squat, you lower yourself towards the ground, balancing on your feet with your legs bent.","ex":{"en":"He squatted, grunting at the pain in his knees","cn":"他蹲在那儿，双膝的伤痛得他直哼哼。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"矮胖的;短粗的","en":"If you describe someone or something as squat, you mean they are short and thick, usually in an unattractive way.","ex":{"en":"Eddie was a short squat fellow in his forties with thinning hair.","cn":"埃迪四十多岁，矮矮胖胖的，头发日渐稀疏。"}},{"pos":"VERB 动词","cn":"擅自占用(闲置房屋或土地)","en":"People who squat occupy an unused building or unused land without having a legal right to do so.","ex":{"en":"You can't simply wander around squatting on other people's property","cn":"你不能这样到处乱窜，擅自占用别人的地产。"}},{"pos":"N-COUNT 可数名词","cn":"被擅自占住的空房","en":"A squat is an empty building that people are living in illegally, without paying any rent or any property tax.","ex":{"en":"After returning from Paris, David moved to a squat in Brixton","cn":"从巴黎回来后，戴维搬进了布里克斯顿的一座空房里住下了。"}}]},"examples":[{"en":"They ended up squatting in the empty houses on Oxford Road.","cn":"他们落得在牛津路偷住空房的境地。"},{"en":"a squat muscular man with a shaven head","cn":"剃光头的矮壮男人"}]},"squirt":{"media":{"uk":"media/uk/squirt__gb_1.mp3","us":"media/us/squirt__us_1.mp3"},"oxford":{"phon":"skwɜːt","pos":"verb","senses":[{"en":"to force liquid, gas, etc. in a thin, fast stream through a narrow opening; to be forced out of a narrow opening in this way","cn":"（使）喷射；喷","g":"[transitive, intransitive]","ex":{"en":"The snake can squirt poison from a distance of a metre.","cn":"这种蛇能把毒液喷一米远。"}},{"en":"to hit somebody/something with a stream of water, gas, etc.","cn":"（用…）向…喷射","g":"[transitive]","ex":{"en":"The children were squirting each other with water from the hose.","cn":"孩子们用软水管相互喷水。"}},{"en":"a thin, fast stream of liquid that comes out of a small opening","cn":"喷射出的一股液体","ex":{"en":"a squirt of perfume","cn":"喷出的一股香水"},"pos":"noun"},{"en":"a word used to refer to somebody short, young or unimportant that you do not like or that you find annoying","cn":"小矮子；小屁孩；无名小辈","lab":"informal, disapproving，，","pos":"noun"}]},"collins":{"senses":[{"pos":"V-ERG 及物/不及物动词","cn":"(使)(液体)喷射","en":"If you squirt a liquid somewhere or if it squirts somewhere, the liquid comes out of a narrow opening in a thin fast stream.","ex":{"en":"Norman cut open his pie and squirted tomato sauce into it","cn":"诺尔曼切开自己的派，往里面挤了点番茄酱。"}},{"pos":"VERB 动词","cn":"朝…喷…","en":"If you squirt something with a liquid, you squirt the liquid at it.","ex":{"en":"I squirted him with water","cn":"我朝他喷水。"}}]},"examples":[{"en":"When I cut the lemon, juice squirted in my eye.","cn":"我切柠檬时，柠檬汁溅到了我眼睛里。"},{"en":"The snake can squirt poison from a distance of a metre.","cn":"这种蛇能把毒液喷射到一米处远。"}]},"squad":{"media":{"uk":"media/uk/squad__gb_1.mp3","us":"media/us/squad__us_1.mp3"},"oxford":{"phon":"skwɒd","pos":"noun","senses":[{"en":"a section of a police force that deals with a particular type of crime","cn":"（对付某类犯罪活动的）警察队伍","ex":{"en":"the drugs/fraud/bomb/riot squad","cn":"缉毒队；反欺诈小组；防爆小组；防暴队"}},{"en":"a group of players, runners, etc. from which a team is chosen for a particular game or match","cn":"运动（代表）队","ex":{"en":"the Olympic/national squad","cn":"奥林匹克代表队；国家队"}},{"en":"a small group of soldiers working or being trained together","cn":"（军队的）班","ex":{"en":"an elite combat squad","cn":"精锐战斗班"}},{"en":"a group of people who have a particular task","cn":"（特殊任务）小组，队","ex":{"en":"She was captain of the cheerleading squad.","cn":"她是啦啦队队长。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(专门处理某类犯罪的)警察分队","en":"A squad is a section of a police force that is responsible for dealing with a particular type of crime.","ex":{"en":"The building was evacuated and the bomb squad called","cn":"大楼里进行了人员疏散，并叫来了拆弹小组。"}},{"pos":"N-COUNT 可数名词","cn":"(将从中挑选运动员组队参赛的)运动队，大名单","en":"A squad is a group of players from which a sports team will be chosen.","ex":{"en":"Sean O'Leary has been named in the England squad to tour Argentina.","cn":"肖恩·奥利里已入选参加阿根廷巡回赛的英格兰队大名单。"}},{"pos":"N-COUNT 可数名词","cn":"班;小队","en":"A squad of soldiers is a small group of them.","ex":{"en":"...a squad of commandos.","cn":"突击小分队"}}]},"examples":[{"en":"They still have not named their squad for the World Cup qualifier.","cn":"他们尚未确定参加世界杯预选赛的运动员名单。"},{"en":"the Olympic/national squad","cn":"奥林匹克代表队；国家队"}]},"square":{"media":{"img":["media/pic/quadrilaterals_comp.jpg","media/thumb/square.jpg"],"uk":"media/uk/square__gb_1.mp3","us":"media/us/square__us_1.mp3"},"oxford":{"phon":"skweə(r)","pos":"adjective","senses":[{"en":"having four straight equal sides and four angles of 90°","cn":"正方形的；四方形的","sc":"shape","ex":{"en":"a square room","cn":"正方形的房间"}},{"en":"forming an angle of 90° exactly or approximately","cn":"成直角的；方的","sc":"shape","ex":{"en":"The book had rounded, not square, corners.","cn":"这本书是圆角的，而不是方角的。"}},{"en":"used after a number to give a measurement of area","cn":"（用于数字后表示面积）平方","sc":"measurement","ex":{"en":"an area of 36 square metres/feet/miles/kilometres/inches","cn":"36 平方米／英尺／英里／公里／英寸的面积"}},{"en":"used after a unit of measurement to say that something measures the same amount on each of four sides","cn":"（用于表示长度的单位后，表示某物四个边等长）…见方的","sc":"measurement","ex":{"en":"a carpet four metres square","cn":"四米见方的地毯"}},{"en":"used to describe something that is broad or that looks solid in shape","cn":"宽阔的；结实的；厚实的","sc":"broad/solid","ex":{"en":"a man of square build","cn":"体格壮实的男子"}},{"en":"level with something or parallel to something","cn":"（和某物）相齐，平行","g":"[not before noun]","sc":"level","ex":{"en":"tables arranged square with the wall","cn":"顺着墙壁摆放的一些桌子"}},{"en":"if two people are square, neither of them owes money to the other","cn":"彼此无欠账的；两清的；结清账的","lab":"informal","sc":"with money","ex":{"en":"Here's the £10 I owe you—now we're square.","cn":"这是我欠你的 10 英镑，这下我们两清了。"}},{"en":"if two teams are square, they have the same number of points","cn":"打平的；平局的","sc":"in sport","ex":{"en":"The teams were all square at half-time.","cn":"两队上半场打成平局。"}},{"en":"fair or honest, especially in business matters","cn":"（尤指在生意上）公平的，公正的，诚实的","sc":"fair/honest","ex":{"en":"a square deal","cn":"公平交易"}},{"en":"in agreement with something","cn":"（与…）一致的，吻合的","sc":"in agreement","ex":{"en":"That isn't quite square with what you said yesterday.","cn":"那跟你昨天所讲的不大吻合。"}},{"en":"considered to be boring, for example because they are old-fashioned or work too hard at school","cn":"乏味的；古板的；太循规蹈矩的","lab":"old-fashioned, informal, disapproving，，，，","sc":"boring"},{"en":"a shape with four straight sides of equal length and four angles of 90°; a piece of something that has this shape","cn":"正方形；四方形；正方形物","g":"[countable]","sc":"shape","ex":{"en":"First break the chocolate into squares.","cn":"先把巧克力掰成方块。"},"pos":"noun"},{"en":"an open area in a town, usually with four sides, surrounded by buildings","cn":"（通常为方形的）广场","g":"[countable]","sc":"in town","ex":{"en":"The hotel is just off the main square.","cn":"旅馆就在大广场附近。"},"pos":"noun"},{"en":"the number obtained when you multiply a number by itself","cn":"平方；二次幂","g":"[countable]","sc":"mathematics","ex":{"en":"The square of 7 is 49.","cn":"7 的平方是 49。"},"pos":"noun"},{"en":"a person who is considered to be boring, for example because they are old-fashioned or because they work too hard at school","cn":"乏味的人；古板的人；老古董；书呆子","g":"[countable]","lab":"old-fashioned, informal, disapproving，，，，","sc":"boring person","pos":"noun"},{"en":"to make something have straight edges and corners","cn":"使成正方形；使成方形","sc":"shape","ex":{"en":"The boat is rounded at the front but squared off at the back.","cn":"这条船船头是圆的，船尾则是方的。"},"pos":"verb"},{"en":"to multiply a number by itself","cn":"使成平方；使成二次幂","g":"[usually passive]","sc":"mathematics","ex":{"en":"Three squared is written 32.","cn":"3 的平方写作 32。"},"pos":"verb"},{"en":"to make your back and shoulders straight to show you are ready or determined to do something","cn":"挺直身子；挺起胸膛","sc":"shoulders","ex":{"en":"Bruno squared himself to face the waiting journalists.","cn":"布鲁诺挺起胸膛面对等候的记者。"},"pos":"verb"},{"en":"to make the number of points you have scored in a game or competition equal to those of your opponents","cn":"（使）打成平局，打平","lab":"especially British English","sc":"in sport","ex":{"en":"His goal squared the game 1–1.","cn":"他进了一球，使比赛打成 1:1 平。"},"pos":"verb"},{"en":"to pay money to somebody in order to get their help","cn":"贿赂；收买；买通","lab":"informal","sc":"pay money","ex":{"en":"They must have squared the mayor before they got their plan underway.","cn":"一定是买通了市长，他们的计划才得以实施。"},"pos":"verb"},{"en":"directly; not at an angle","cn":"正对着地；径直地","ex":{"en":"I looked her square in the face.","cn":"我直视着她的脸。"},"pos":"adverb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"正方形;四方形","en":"A square is a shape with four sides that are all the same length and four corners that are all right angles.","ex":{"en":"Serve the cake warm or at room temperature, cut in squares","cn":"等蛋糕温热或凉至室温时切成四方块端上桌。"}},{"pos":"N-COUNT; N-IN-NAMES 名称名词；名称名词","cn":"(通常为方形的)广场","en":"In a town or city, a square is a flat open place, often in the shape of a square.","ex":{"en":"The house is located in one of Pimlico's prettiest garden squares","cn":"房子位于皮姆利科最美丽的一个花园广场上。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"正方形的;方的","en":"Something that is square has a shape the same as a square or similar to a square.","ex":{"en":"Round tables seat more people in the same space as a square table","cn":"在相同的空间里，圆桌比起方桌可以坐下更多的人。"}},{"pos":"ADJ 形容词","cn":"(用于长度单位前表示面积)平方的","en":"Square is used before units of length when referring to the area of something. For example, if something is three metres long and two metres wide, its area is six square metres.","ex":{"en":"Canary Wharf was set to provide 10 million square feet of office space","cn":"金丝雀码头计划要提供 1,000 万平方英尺的办公面积。"}},{"pos":"ADJ 形容词","cn":"(用于长度面积后表示四方形物的边长)长宽为…的","en":"Square is used after units of length when you are giving the length of each side of something that is square in shape.","ex":{"en":"...a linen cushion cover, 45 cm square.","cn":"一个亚麻靠垫套，长宽为 45 厘米"}},{"pos":"VERB 动词","cn":"使成二次幂;将(数字)平方","en":"To square a number means to multiply it by itself. For example, 3 squared is 3 x 3, or 9. 3 squared is usually written as 32.","ex":{"en":"Take the time in seconds, square it, and multiply by 5.12","cn":"记下用了多少秒时间，将其平方，再乘以5.12。"}},{"pos":"N-COUNT 可数名词","cn":"二次幂;平方","en":"The square of a number is the number produced when you multiply that number by itself. For example, the square of 3 is 9.","ex":{"en":"...the square of the speed of light, an exceedingly large number.","cn":"光速的平方，一个天文数字"}},{"pos":"V-ERG 及物/不及物动词","cn":"(使)(不同想法或行动)协调一致","en":"If you square two different ideas or actions with each other or if they square with each other, they fit or match each other.","ex":{"en":"That explanation squares with the facts, doesn't it","cn":"那个解释和事实相符，不是吗？"}},{"pos":"VERB 动词","cn":"就…征得…的同意","en":"If you square something with someone, you ask their permission or check with them that what you are doing is acceptable to them.","ex":{"en":"I squared it with Dan, who said it was all right so long as I was back next Monday morning","cn":"我征得了丹的同意，他说只要我下周一早上能回来就行。"}},{"pos":"PHRASE 短语","cn":"将圆的变成方的;做不可能做到的事","en":"If you say that someone squares the circle, you mean that they bring together two things which are normally thought to be so different that they cannot exist together.","ex":{"en":"He has squared the circle of keeping the City happy and doing something to improve business cash flow","cn":"他做到了不可能做到的事，既让伦敦城满意，又增加了企业的现金流量。"}},{"pos":"PHRASE 短语","cn":"(因行动失败而)重新开始，重起炉灶","en":"If you are back to square one, you have to start dealing with something from the beginning again because the way you were dealing with it has failed.","ex":{"en":"If your complaint is not upheld, you may feel you are back to square one","cn":"如果你的投诉没有得到支持，你可能会感到自己又得重新开始。"}},{"pos":"PHRASE 短语","cn":"不适宜做某工作的人;与环境格格不入的人","en":"If you describe someone as a square peg in a round hole, you mean that they are completely unsuitable for the job they are doing or the situation they are in.","ex":{"en":"Taylor is clearly the wrong man for the job—a square peg in a round hole.","cn":"泰勒显然不是做这份工作的合适人选——简直就是方枘圆凿。"}},{"pos":"","cn":"","en":"fair and square→see: ;"},{"pos":"","cn":"","en":"相关词组：square away square off square up"}]},"examples":[{"en":"He looks as though he hasn't had a square meal for weeks.","cn":"看他那样子，就好像几个星期没吃过一顿像样的饭了。"},{"en":"It was like trying to square a circle. That is, it was impossible.","cn":"这就好比要把圆的变成方的。也就是说，是不可能的。"}]},"squeezing":{"lemma":"squeeze"},"squeeze":{"oxford":{"phon":"skwiːz","pos":"verb","senses":[{"en":"to press something, especially with your fingers","cn":"挤压；捏","g":"[transitive, intransitive]","sc":"press with fingers","ex":{"en":"to squeeze a tube of toothpaste","cn":"挤牙膏"}},{"en":"to get liquid out of something by pressing or twisting it hard","cn":"（从某物中）榨出，挤出，拧出","g":"[transitive]","lab":"figurative","sc":"get liquid out","ex":{"en":"to squeeze the juice from a lemon","cn":"把柠檬的汁挤出来"}},{"en":"to force somebody/something/yourself into or through a small space","cn":"（使）挤入；挤过；塞入","g":"[transitive, intransitive]","lab":"figurative","sc":"into/through small space","ex":{"en":"We managed to squeeze six people into the car.","cn":"我们往那辆车上挤进了六个人。"}},{"en":"to get something by putting pressure on somebody, threatening them, etc.","cn":"向…勒索（或榨取）；逼迫…给","g":"[transitive]","lab":"informal","sc":"threaten","ex":{"en":"He's squeezing me for £500.","cn":"他逼我拿出 500 英镑。"}},{"en":"to strictly limit or reduce the amount of money that somebody/something has or can use","cn":"严格限制，削减，紧缩（资金）","g":"[transitive]","sc":"limit money","ex":{"en":"High interest rates have squeezed the industry hard.","cn":"高利率使这个行业举步维艰。"}},{"en":"an act of pressing something, usually with your hands","cn":"挤压；捏","g":"[countable, usually singular]","sc":"pressing with fingers","ex":{"en":"He gave my hand a little squeeze.","cn":"他轻轻捏了捏我的手。"},"pos":"noun"},{"en":"a small amount of liquid that is produced by pressing something","cn":"榨出的液体；少量挤出的汁","g":"[countable]","sc":"of liquid","ex":{"en":"a squeeze of lemon juice","cn":"挤出的一点儿柠檬汁"},"pos":"noun"},{"en":"a situation where it is almost impossible for a number of people or things to fit into a small or limited space","cn":"挤；塞","g":"[singular]","sc":"in small space","ex":{"en":"It was a tight squeeze but we finally got everything into the case.","cn":"箱子塞得很紧，不过我们最终还是把所有东西都装进去了。"},"pos":"noun"},{"en":"a reduction in the amount of money, jobs, etc. available; a difficult situation caused by this","cn":"（可获得的钱、工作岗位等的）减少，削减；拮据；经济困难","g":"[countable, usually singular]","sc":"reduction in money","ex":{"en":"We're really feeling the squeeze since I lost my job.","cn":"自从我丢了工作后，我们的确感觉到手头拮据。"},"pos":"noun"},{"en":"a boyfriend or girlfriend","cn":"男朋友；女朋友","g":"[singular]","lab":"especially North American English, informal，，","sc":"boyfriend/girlfriend","ex":{"en":"Who's his main squeeze?","cn":"他最要好的女朋友是谁？"},"pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"(通常指用手)挤压，捏","en":"If you squeeze something, you press it firmly, usually with your hands.","ex":{"en":"He squeezed her arm reassuringly","cn":"他安慰地捏了捏她的胳膊。"}},{"pos":"VERB 动词","cn":"压榨，挤出(液体或软的东西)","en":"If you squeeze a liquid or a soft substance out of an object, you get the liquid or substance out by pressing the object.","ex":{"en":"Joe put the plug in the sink and squeezed some detergent over the dishes.","cn":"乔用塞子塞住水槽，往盘子上挤了点洗涤剂。"}},{"pos":"V-ERG 及物/不及物动词","cn":"(常因害怕或保护眼睛而)紧闭(双眼)","en":"If you squeeze your eyes shut or if your eyes squeeze shut, you close them tightly, usually because you are frightened or to protect your eyes from something such as strong sunlight.","ex":{"en":"Nancy squeezed her eyes shut and prayed","cn":"南希紧闭双眼祈祷着。"}},{"pos":"V-ERG 及物/不及物动词","cn":"挤过;挤进;塞进","en":"If you squeeze a person or thing somewhere or if they squeeze there, they manage to get through or into a small space.","ex":{"en":"They lowered him gradually into the cockpit. Somehow they squeezed him in the tight space, and strapped him in","cn":"他们将他慢慢向下放入驾驶舱，设法将他塞进了狭小的空间，并给他系好安全带。"}},{"pos":"N-SING 单数名词","cn":"拥挤","en":"If you say that getting a number of people into a small space is a squeeze, you mean that it is only just possible for them all to get into it.","ex":{"en":"It was a squeeze in the car with five of them","cn":"车里坐了他们 5 个人，很拥挤。"}},{"pos":"VERB 动词","cn":"(通过劝说)榨取，获取","en":"If you squeeze something out of someone, you persuade them to give it to you, although they may be unwilling to do this.","ex":{"en":"The investigators complained about the difficulties of squeezing information out of residents","cn":"调查人员抱怨说很难从居民身上获取信息。"}},{"pos":"VERB 动词","cn":"紧缩，压缩(经济)","en":"If a government squeezes the economy, they put strict controls on people's ability to borrow money or on their own departments' freedom to spend money, in order to control the country's rate of inflation.","ex":{"en":"The government will squeeze the economy into a severe recession to force inflation down","cn":"政府将紧缩经济，使之出现严重衰退，以此迫使通货膨胀率下降。"}},{"pos":"N-COUNT 可数名词","cn":"男(或女)朋友","en":"Someone's squeeze is their boyfriend or girlfriend.","ex":{"en":"Jack showed off his latest squeeze at the weekend.","cn":"周末杰克炫耀了一番自己新交的女朋友。"}},{"pos":"","cn":"","en":"相关词组：squeeze off squeeze out"}]},"media":{"img":["media/ldoce/img/squeeze.jpg","media/pic/squeeze_comp.jpg"],"uk":"media/uk/squeeze__gb_1.mp3","us":"media/us/squeeze__us_1.mp3"},"examples":[{"en":"It was a tight squeeze but we finally got everything into the case.","cn":"箱子塞得很紧，不过我们最终还是把所有东西都装进去了。"},{"en":"to squeeze into a tight dress/a parking space","cn":"勉强穿上一件窄连衣裙；把车勉强开进一个停车位"}]},"squeezed":{"lemma":"squeeze"},"squashed":{"lemma":"squash","media":{"uk":"media/ldoce/hwd/bre/0/squashed0205.mp3","us":"media/ldoce/hwd/ame/0/laadsquashed.mp3"}},"squares":{"lemma":"square"},"squiggly":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(线条)不规则的，弯弯曲曲的","en":"Squiggly lines are lines that bend and curl in an irregular way.","ex":{"en":"He drew three squiggly lines.","cn":"他画了 3 条弯弯曲曲的线。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a line with irregular curves","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/1/squiggle0205.mp3","us":"media/ldoce/hwd/ame/5/squiggle1.mp3"},"examples":[{"en":"Shorthand just looks like a series of funny squiggles to me.","cn":""}],"oxford":{"phon":"ˈskwɪɡli","pos":"adjective","senses":[{"en":"squiggly lines are drawn or written in a careless way with curves and waves in them","cn":"弯曲的：用曲线或波浪以粗心的方式绘制或书写弯曲的线条"}]}},"squire":{"collins":{"senses":[{"pos":"N-COUNT; N-TITLE 可数名词；头衔名词","cn":"(旧时英国的)乡绅，大地主","en":"In former times, the squire of an English village was the man who owned most of the land in it."},{"pos":"N-VOC 称呼名词","cn":"先生(有些男性对不相识的同性友好的尊称)","en":"Some men use squire to address a man they do not know in a friendly but respectful way.","ex":{"en":"Hard luck, squire.","cn":"运气真差，先生。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the man who in the past owned most of the land around a country village in England 〔","cn":"旧时英格兰乡村的〕大地主﹐乡绅"},{"en":"a young man in the Middle Ages who learned how to be a knight by serving one 〔","cn":"中世纪骑士的〕扈从﹐随从"},{"en":"used by some men to address a man when they do not know his name","cn":"先生〔某些男人对不知道姓名的男性的称呼〕"}]},"vocab":{"pos":"n v","senses":[{"en":"Squire is a British term for a country landowner or gentleman. You can use squire to describe a refined and powerful man, or as a verb meaning to escort: when the queen visited, the police chief squired her around town."}]},"media":{"uk":"media/ldoce/hwd/bre/8/squire0205.mp3","us":"media/ldoce/hwd/ame/4/squire1.mp3"},"examples":[{"en":"What can I get you, Squire?","cn":"您要点什么，先生？"}],"oxford":{"phon":"ˈskwaɪə(r)","pos":"noun","senses":[{"en":"(in the past in England) a man of high social status who owned most of the land in a particular country area","cn":"（英格兰旧时的）乡绅，大地主","ex":{"en":"a country squire","cn":"乡绅"}},{"en":"used by a man as a friendly way of addressing another man","cn":"（男子对另一男子的友好称呼）先生","lab":"British English, informal or humorous，，","ex":{"en":"What can I get you, Squire?","cn":"您要点什么，先生？"}},{"en":"(in the past) a young man who was an assistant to a knight before becoming a knight himself","cn":"（旧时骑士的）扈从"}]}},"squib":{"collins":{"senses":[{"pos":"PHRASE 短语","cn":"未取得预期效果的事;失败;落空","en":"You can describe something such as an event or a performance as a damp squib when it is expected to be interesting, exciting, or impressive, but fails to be any of these things.","ex":{"en":"The all-party meeting was a damp squib.","cn":"全党大会没有取得预期效果。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a small exploding firework","cn":"小爆竹﹐甩炮"},{"en":"a short amusing piece of writing that attacks someone","cn":"讽刺短文"}]},"media":{"uk":"media/ldoce/hwd/bre/a/ld41squib.mp3","us":"media/ldoce/hwd/ame/e/squib.mp3"},"oxford":{"phon":"skwɪb","pos":"noun","senses":[{"en":"a small firework","cn":"小爆竹"}]}},"squander":{"collins":{"senses":[{"pos":"VERB 动词","cn":"浪费，挥霍(金钱、资源、机遇等)","en":"If you squander money, resources, or opportunities, you waste them.","ex":{"en":"Hooker didn't squander his money on flashy cars or other vices","cn":"胡克没有将自己的钱浪费在豪华轿车或其他恶习上。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to use money to buy things","cn":""},{"en":"to spend all of an amount of money over a period of time – used especially when saying that someone spends a lot of money","cn":""},{"en":"to spend a lot of money in order to do something, because you think it is important or special","cn":""}]},"vocab":{"pos":"v","senses":[{"en":"To squander means to spend extravagantly, thoughtlessly, or wastefully. If you need to save for college, don't squander her income on nightly sushi dinners."}]},"media":{"uk":"media/ldoce/hwd/bre/8/squander0205.mp3","us":"media/ldoce/hwd/ame/8/squander.mp3"},"examples":[{"en":"He squandered all his money on gambling.","cn":"他把自己所有的钱都糟蹋在赌博上了。"},{"en":"The home team squandered a number of chances in the first half.","cn":"主队在上半场浪费了几次机会。"}],"oxford":{"phon":"ˈskwɒndə(r)","pos":"verb","senses":[{"en":"to waste money, time, etc. in a stupid or careless way","cn":"浪费，挥霍（金钱、时间等）","ex":{"en":"He squandered all his money on gambling.","cn":"他把自己所有的钱都挥霍在赌博上了。"}}]}},"squarely":{"collins":{"senses":[{"pos":"ADV 副词","cn":"径直;正中地","en":"Squarely means directly or in the middle, rather than indirectly or at an angle.","ex":{"en":"I kept the gun aimed squarely at his eyes.","cn":"我一直将枪径直瞄准他的双眼。"}},{"pos":"ADV 副词","cn":"完全地;毫无疑问地","en":"If something such as blame or responsibility lies squarely with someone, they are definitely the person responsible.","ex":{"en":"The president put the blame squarely on his opponent","cn":"总统将责任完全归咎于对手。"}},{"pos":"ADV 副词","cn":"直截了当地;不回避地","en":"If you face something squarely, you face it directly, without trying to avoid it.","ex":{"en":"The management committee have faced the situation squarely","cn":"管理委员会直面当前形势。"}}]},"ldoce":{"phon":"hwd","pos":"adverb","senses":[{"en":"directly and firmly","cn":"直接地﹔果断地"},{"en":"completely and with no doubt","cn":"完全地﹐毫无疑问地"},{"en":"straight on something and centrally","cn":"端端正正地"}]},"media":{"uk":"media/ldoce/hwd/bre/5/squarely0205.mp3","us":"media/ldoce/hwd/ame/a/squarely.mp3"},"examples":[{"en":"He stood squarely in front of them, blocking the entrance.","cn":"他就对着他们站在那里，挡住入口。"},{"en":"( figurative ) We must meet the challenge squarely (= not try to avoid it).","cn":"我们必须正面迎接这一挑战。"}],"oxford":{"phon":"ˈskweəli","pos":"adverb","senses":[{"en":"directly; not at an angle or to one side","cn":"正对着地；径直地；不偏不倚地","lab":"figurative","ex":{"en":"She looked at me squarely in the eye.","cn":"她直直地看着我的眼睛。"}},{"en":"directly or exactly; without doubt","cn":"直截了当；明确无误；毫无疑问地","ex":{"en":"The responsibility for the crisis rests squarely on the government.","cn":"这一危机的责任全在政府。"}}]}},"squid":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"枪乌贼;鱿鱼","en":"A squid is a sea creature with a long soft body and many soft arms called tentacles.","ex":{"en":"Add the prawns and squid and cook for 2 minutes.","cn":"放入对虾和鱿鱼，烹炒 2 分钟。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a sea creature with a long soft body and ten arms around its mouth","cn":"枪乌贼﹐鱿鱼"}]},"media":{"img":["media/ldoce/img/squid.jpg"],"uk":"media/ldoce/hwd/bre/7/squid0205.mp3","us":"media/ldoce/hwd/ame/0/squid.mp3"},"oxford":{"phon":"skwɪd","pos":"noun","senses":[{"en":"a sea creature that has a long soft body, eight arms and two tentacles (= long thin parts like arms) around its mouth, and that is sometimes used for food","cn":"枪乌贼；鱿鱼"}]}},"squalid":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"肮脏的;邋遢的;条件差的","en":"A squalid place is dirty, untidy, and in bad condition.","ex":{"en":"He followed her up a rickety staircase to a squalid bedsit","cn":"他跟着她上了一段摇摇晃晃的楼梯，来到了一间邋遢的卧室起居室两用房间。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(行为)卑鄙的，丑恶的","en":"Squalid activities are unpleasant and often dishonest.","ex":{"en":"The Tory Party called the bill 'the most squalid measure ever put before the Commons'.","cn":"保守党称该议案为“有史以来向下议院提出的最卑鄙的议案”。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"not clean","cn":""},{"en":"very dirty","cn":""},{"en":"covered with mud","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"Squalid things appear neglected, or morally repulsive in nature, like a frat house after a semester of hard partying and zero cleanup."}]},"media":{"uk":"media/ldoce/hwd/bre/c/squalid0205.mp3","us":"media/ldoce/hwd/ame/b/squalid.mp3"},"examples":[{"en":"It was a squalid affair involving prostitutes and drugs.","cn":"那是一桩涉及卖淫与毒品的丑事。"},{"en":"squalid, overcrowded refugee camps","cn":"肮脏而拥挤的难民营"}],"oxford":{"phon":"ˈskwɒlɪd","pos":"adjective","senses":[{"en":"very dirty and unpleasant","cn":"肮脏的；邋遢的","ex":{"en":"squalid housing","cn":"肮脏的房屋"}},{"en":"involving low moral standards or dishonest behaviour","cn":"道德败坏的；丑恶的；卑鄙的","ex":{"en":"It was a squalid affair involving prostitutes and drugs.","cn":"那是一桩涉及娼妓与毒品的丑事。"}}]}},"squalor":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"肮脏;邋遢;恶劣条件","en":"You can refer to very dirty, unpleasant conditions as squalor .","ex":{"en":"He was out of work and living in squalor.","cn":"他失业了，生活潦倒。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the condition of being dirty and unpleasant because of a lack of care or money 〔","cn":"环境〕邋遢﹐肮脏"}]},"vocab":{"pos":"n","senses":[{"en":"If something is extremely dirty, filthy or just plain disgusting, it falls into the territory of the noun squalor . We’re not just talking about a messy room. We’re talking about a dungeon riddled with rats and roaches."}]},"collocations":{"phrases":["ADJ. public, urban","VERB + SQUALOR live in","PREP. amid/in the ~ of a beautiful garden amid the squalor of the slums | in ~ He was born in squalor next to London's docks."]},"media":{"uk":"media/ldoce/hwd/bre/9/squalor0205.mp3","us":"media/ldoce/hwd/ame/f/squalor.mp3"},"examples":[{"en":"He had lost his job and was living in squalor.","cn":"他丢了工作，过得很糟糕。"},{"en":"the poverty and squalor of the slums","cn":"贫民窟的贫穷和肮脏"}],"oxford":{"phon":"ˈskwɒlə(r)","pos":"noun","senses":[{"en":"dirty and unpleasant conditions","cn":"肮脏；邋遢","ex":{"en":"the poverty and squalor of the slums","cn":"贫民窟的贫穷和肮脏"}}]}},"squaw":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(旧时用法)美洲印第安女人","en":"In the past, people sometimes referred to a Native American Indian woman as a squaw ."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a word for a Native American woman, now usually considered offensive","cn":"美洲土著女子〔现在一般认为该词具有冒犯性〕"}]},"vocab":{"pos":"n","senses":[{"en":"A squaw is an old Native American word for woman or wife. The word squaw not often used anymore because people find it offensive."}]},"media":{"uk":"media/ldoce/hwd/bre/d/ld41squaw.mp3","us":"media/ldoce/hwd/ame/6/squaw.mp3"},"oxford":{"phon":"skwɔː","pos":"noun","senses":[{"en":"an offensive word for an indigenous North American woman","cn":"美洲印第安女人（常含冒犯意）"}]}},"squabble":{"collins":{"senses":[{"pos":"V-RECIP 相互动词","cn":"(为琐事)争吵，起争执","en":"When people squabble, they quarrel about something that is not really important.","ex":{"en":"Mother is devoted to Dad although they squabble all the time","cn":"母亲很爱父亲，尽管他们总是为琐事拌嘴。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to speak angrily to someone because you disagree with them about something","cn":""},{"en":"to argue with someone for a period of time about a particular thing","cn":""},{"en":"to have an argument with someone, especially with your boyfriend, girlfriend, or a member of your family","cn":""}]},"vocab":{"pos":"n v","senses":[{"en":"A squabble is a fight but not necessarily a serious one. When we squabble , we have a little argument, probably about something not too important."}]},"collocations":{"phrases":["ADJ. petty | bitter | domestic, family | internal","VERB + SQUABBLE have | resolve, settle","PREP. ~ about/over squabbles about money | ~ among/between I always have to settle squabbles between the children. | ~ with a squabble with "]},"media":{"uk":"media/ldoce/hwd/bre/f/squabble0205.mp3","us":"media/ldoce/hwd/ame/7/squabble.mp3"},"examples":[{"en":"My sisters were squabbling over what to watch on TV.","cn":"我的姐妹正为看哪个电视节目争吵。"},{"en":"There were endless squabbles over who should sit where.","cn":"为谁该坐哪儿吵个没完没了。"}],"oxford":{"phon":"ˈskwɒbl","pos":"verb","senses":[{"en":"to argue noisily about something that is not very important","cn":"（为小事）争吵，发生口角","ex":{"en":"My sisters were squabbling over what to watch on TV.","cn":"我的姐妹正为看哪个电视节目争吵。"}},{"en":"a noisy argument about something that is not very important","cn":"（为小事）争吵，发生口角","ex":{"en":"family squabbles","cn":"家庭口角"},"pos":"noun"}]}},"squadron":{"collins":{"senses":[{"pos":"N-COUNT-COLL 可数集合名词","cn":"(尤指空军的)中队","en":"A squadron is a section of one of the armed forces, especially the air force.","ex":{"en":"The government said it was preparing a squadron of eighteen Mirage fighter planes.","cn":"政府称其正筹建一个由18架“幻影”战斗机组成的空军中队。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a military force consisting of a group of aircraft or ships","cn":"飞行中队﹔海军分遣舰队"}]},"vocab":{"pos":"n","senses":[{"en":"In the military, a squadron is a small unit sent out from the main group to do some particular task. In the air force, for example, a squadron might fly out on a surveillance mission."}]},"media":{"uk":"media/ldoce/hwd/bre/8/squadron0205.mp3","us":"media/ldoce/hwd/ame/e/squadron1103.mp3"},"examples":[{"en":"a bomber/fighter squadron","cn":"轰炸机/战斗机中队"}],"oxford":{"phon":"ˈskwɒdrən","pos":"noun","senses":[{"en":"a group of military aircraft or ships forming a section of a military force","cn":"（空军或海军的）中队","ex":{"en":"a bomber/fighter squadron","cn":"轰炸机／战斗机中队"}}]}},"squash":{"collins":{"senses":[{"pos":"VERB 动词","cn":"压扁;压坏;压碎","en":"If someone or something is squashed, they are pressed or crushed with such force that they become injured or lose their shape.","ex":{"en":"Robert was lucky to escape with just a broken foot after being squashed against a fence by a car","cn":"罗伯特很幸运，他被一辆轿车挤压到一排栅栏上后只是一只脚骨折。"}},{"pos":"ADJ 形容词","cn":"使…挤进;把…塞进","en":"If people or things are squashed into a place, they are put or pushed into a place where there is not enough room for them to be.","ex":{"en":"There were 2000 people squashed into her recent show","cn":"2,000人挤进去观看她最近的一次演出。"}},{"pos":"N-SING 单数名词","cn":"拥挤","en":"If you say that getting a number of people into a small space is a squash, you mean that it is only just possible for them all to get into it.","ex":{"en":"It all looked a bit of a squash as they squeezed inside the small hatchback.","cn":"当他们挤进那辆小小的舱门式汽车时，看起来有些过于拥挤。"}},{"pos":"VERB 动词","cn":"镇压;压制;粉碎","en":"If you squash something that is causing you trouble, you put a stop to it, often by force.","ex":{"en":"The troops would stay in position to squash the first murmur of trouble.","cn":"部队将继续原地驻扎，一有骚乱迹象就立即镇压。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"壁球","en":"Squash is a game in which two players hit a small rubber ball against the walls of a court using rackets."},{"pos":"N-MASS 物质名词","cn":"果汁饮料(通常为浓缩瓶装，饮时掺水)","en":"Squash is a drink made from fruit juice, sugar, and water. Squash is sold in bottles in a concentrated form to which you add water.","ex":{"en":"...a glass of orange squash.","cn":"一杯橙汁饮料"}},{"pos":"N-VAR 可变名词","cn":"番瓜类蔬菜","en":"A squash is one of a family of vegetables that have thick skin and soft or firm flesh inside."}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to push something down or against a surface with your fingers or foot","cn":""},{"en":"to press something inwards from both sides","cn":""},{"en":"to press something against a surface accidentally and damage it by making it flat","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/5/squash_v0205.mp3","us":"media/ldoce/hwd/ame/3/squash1.mp3","img":["media/pic/squash_comp.jpg","media/thumb/squash.jpg"]},"examples":[{"en":"If parents don't answer children's questions, their natural curiosity will be squashed.","cn":"如果父母不回答孩子的问题，就会挫伤他们好奇的天性。"},{"en":"It's a real squash with six of us in the car.","cn":"我们六个人坐在这辆车上，可真够挤的。"}],"oxford":{"phon":"skwɒʃ","pos":"verb","senses":[{"en":"to press something so that it becomes soft, damaged or flat, or changes shape","cn":"压软（或挤软、压坏、压扁等）；把…压（或挤）变形","g":"[transitive]","ex":{"en":"The tomatoes at the bottom of the bag had been squashed.","cn":"袋底的西红柿给压烂了。"}},{"en":"to push somebody/something or yourself into a space that is too small","cn":"（使）挤进；塞入","g":"[intransitive, transitive]","ex":{"en":"We all squashed into the back of the car.","cn":"我们都挤到了汽车后部。"}},{"en":"to stop something from continuing; to destroy something because it is a problem for you","cn":"打断；制止；去除；粉碎","g":"[transitive]","ex":{"en":"to squash a plan/an idea/a revolt","cn":"使计划落空；否定想法；镇压反叛"}},{"en":"a game for two players, played in a court surrounded by four walls, using rackets and a small rubber ball","cn":"（软式）墙网球；壁球","g":"[uncountable]","lab":"formal","ex":{"en":"a squash court","cn":"壁球场"},"pos":"noun"},{"en":"a drink made with fruit juice, sugar and water","cn":"果汁饮料","g":"[uncountable, countable]","lab":"British English","ex":{"en":"a glass of orange/lemon squash","cn":"一杯橙汁／柠檬汁"},"pos":"noun"},{"en":"a type of vegetable that grows on the ground. Winter squash have hard skin and are orange inside. Summer squash have soft yellow or green skin and are white inside.","cn":"南瓜小果（主要种类为笋瓜 winter squash 和西葫芦 summer squash）","g":"[countable, uncountable]","pos":"noun"},{"en":"if something is a squash, there is hardly enough room for everything or everyone to fit into a small space","cn":"拥挤的环境（或处所）","g":"[singular]","lab":"informal","ex":{"en":"It's a real squash with six of us in the car.","cn":"我们六个人坐在这辆车上，可真够挤的。"},"pos":"noun"}]}},"squashy":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"柔软易压坏的","en":"Squashy things are soft and able to be squashed easily.","ex":{"en":"...deep, squashy sofas.","cn":"深凹下去的软沙发"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"not hard, firm, or stiff, but easy to press","cn":""},{"en":"used about meat or vegetables that are soft and easy to cut, especially because they have been well cooked","cn":""},{"en":"very wet and too soft, in a way that seems unpleasant – used about bread, vegetables, and the ground","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/e/ld41squashy.mp3","us":"media/ldoce/hwd/ame/e/ld41squashy.mp3"},"oxford":{"phon":"ˈskwɒʃi","pos":"adjective","senses":[{"en":"soft and easy to change or damage","cn":"软而易压坏（或压扁）的","ex":{"en":"a squashy leather armchair","cn":"柔软的皮革扶手椅"}}]}},"squiggle":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"不规则的曲线;波形曲线","en":"A squiggle is a line that bends and curls in an irregular way."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a line with irregular curves","cn":"扭曲[不规则]的线条"}]},"media":{"uk":"media/ldoce/hwd/bre/1/squiggle0205.mp3","us":"media/ldoce/hwd/ame/5/squiggle1.mp3"},"examples":[{"en":"Are these dots and squiggles supposed to be your signature?","cn":"这一堆点点画画就是你的签名吗？"},{"en":"Shorthand just looks like a series of funny squiggles to me.","cn":"速记在我看来就像是一串扭来扭去的奇怪线条。"}],"oxford":{"phon":"ˈskwɪɡl","pos":"noun","senses":[{"en":"a line, for example in somebody’s handwriting, that is drawn or written in a careless way with curves and waves in it","cn":"（写或画的）弯弯曲曲的线条；潦草的笔迹","ex":{"en":"Are these dots and squiggles supposed to be your signature?","cn":"这一堆点点画画就是你的签名吗？"}}]}},"squirm":{"collins":{"senses":[{"pos":"VERB 动词","cn":"(通常指因紧张不安或不适而)扭动，动来动去","en":"If you squirm, you move your body from side to side, usually because you are nervous or uncomfortable.","ex":{"en":"He had squirmed and wriggled and screeched when his father had washed his face","cn":"父亲给他洗脸时，他扭来扭去，尖声喊叫。"}},{"pos":"VERB 动词","cn":"窘迫不安;难为情","en":"If you squirm, you are very embarrassed or ashamed.","ex":{"en":"Mentioning religion is a sure way to make him squirm.","cn":"一提宗教就肯定会让他感到窘迫不安。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to go to a different place, or change the position of your body","cn":""},{"en":"to move slowly from one side to the other","cn":""},{"en":"to move repeatedly from one side to another, with small gentle movements","cn":""}]},"collocations":{"phrases":["ADV. uncomfortably | silently | visibly","VERB + SQUIRM make sb The very mention of her singing made her squirm uncomfortably.","PREP. at He squirmed visibly at the thought of his secret being revealed. | in/with He squirmed with embarrassment."]},"media":{"uk":"media/ldoce/hwd/bre/4/squirm0205.mp3","us":"media/ldoce/hwd/ame/f/squirm.mp3"},"examples":[{"en":"It made him squirm to think how badly he'd messed up the interview.","cn":"一想到自己把面试搞得有多糟，他就觉得无地自容。"},{"en":"The children were squirming restlessly in their seats.","cn":"孩子们在位子上心神不定地动来动去。"}],"oxford":{"phon":"skwɜːm","pos":"verb","senses":[{"en":"to move around a lot making small twisting movements, because you are nervous, uncomfortable, etc.","cn":"（因紧张、不舒服等）动来动去，来回扭动，坐卧不宁","g":"[intransitive]","ex":{"en":"The children were squirming restlessly in their seats.","cn":"孩子们在位子上心神不定地动来动去。"}},{"en":"to feel very embarrassed or ashamed","cn":"十分尴尬；羞愧难当；无地自容","g":"[intransitive]","ex":{"en":"It made him squirm to think how badly he'd messed up the interview.","cn":"一想到自己把面试搞得有多糟，他就觉得无地自容。"}}]}},"squeamish":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"易受惊的;易生气的;神经质的","en":"If you are squeamish, you are easily upset by unpleasant sights or situations.","ex":{"en":"I'm terribly squeamish. I can't bear gory films","cn":"我非常容易受到惊吓。我受不了暴力血腥的电影。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"easily shocked or upset, or easily made to feel sick by seeing unpleasant things","cn":"易受惊的﹔易恶心的﹔神经脆弱的"},{"en":"people who are squeamish","cn":"神经脆弱的人"}]},"vocab":{"pos":"adj","senses":[{"en":"If you fainted or threw up at the sight of frog intestines in biology class, you’re squeamish — easily nauseated or shocked by unpleasant, icky things. No horror movies for you!"}]},"media":{"uk":"media/ldoce/hwd/bre/8/squeamish0205.mp3","us":"media/ldoce/hwd/ame/e/squeamish.mp3"},"examples":[{"en":"This movie is not for the squeamish.","cn":"这部电影不是给神经脆弱的人看的。"},{"en":"His new novel is not for the squeamish .","cn":"他的新小说不是给神经脆弱的人看的。"}],"oxford":{"phon":"ˈskwiːmɪʃ","pos":"adjective","senses":[{"en":"easily upset, or made to feel sick by unpleasant sights or situations, especially when the sight of blood is involved","cn":"易心烦意乱的；易恶心的；神经脆弱的"},{"en":"not wanting to do something that might be considered dishonest or wrong","cn":"诚实谨慎的；正派的"},{"en":"people who are squeamish","cn":"易心烦意乱的人；神经脆弱的人","g":"[plural]","ex":{"en":"This movie is not for the squeamish.","cn":"这部电影不是给神经脆弱的人看的。"}}]}},"squelch":{"collins":{"senses":[{"pos":"VERB 动词","cn":"发吧唧声，发扑哧声(像走在烂泥地里似的)","en":"To squelch means to make a wet, sucking sound, like the sound you make when you are walking on wet, muddy ground.","ex":{"en":"He squelched across the turf","cn":"他扑哧扑哧地走过草皮。"}},{"pos":"VERB 动词","cn":"制止，压制，遏制(谣言、反对势力)","en":"If you squelch something that is causing you trouble, for example rumours or opposition, you firmly put a stop to it.","ex":{"en":"The President wants to squelch any perception that the meeting is an attempt to negotiate.","cn":"总统想要消除任何视本次会议为谈判尝试的看法。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"the sound that a liquid makes when it falls from a height, hits something hard, or is moved rapidly around","cn":""},{"en":"to make a sound like someone walking in soft, wet mud, or to move somewhere making this sound","cn":""},{"en":"if something such as a stream gurgles , it makes a low irregular sound like water flowing through a pipe","cn":""}]},"vocab":{"pos":"v n","senses":[{"en":"When you squelch something, you're putting an end to it. You can squelch an idea or a rebellion."}]},"media":{"uk":"media/ldoce/hwd/bre/9/squelch0205.mp3","us":"media/ldoce/hwd/ame/5/squelch.mp3"},"examples":[{"en":"Her wet shoes squelched at every step.","cn":"她的鞋里进了水，走一步吧唧一声。"},{"en":"We squelched across the muddy field.","cn":"我们扑哧扑哧地穿过泥泞的田地。"}],"oxford":{"phon":"skweltʃ","pos":"verb","senses":[{"en":"to make a quiet sound by pressing something soft and wet","cn":"（挤压湿软物）发吧唧声，发扑哧声","g":"[intransitive]","ex":{"en":"The mud squelched as I walked through it.","cn":"我扑哧扑哧地穿过泥泞。"}},{"en":"to stop something from growing, increasing or developing","cn":"制止；压制；遏制；限制","g":"[transitive]","lab":"North American English","ex":{"en":"to squelch a rumor","cn":"制止谣言"}},{"en":"a quiet sound made by pressing something soft and wet","cn":"发吧唧声，发扑哧声（如走在泥泞中似的）","ex":{"en":"He pulled his foot out of the mud with a squelch.","cn":"他扑哧一声把脚从泥里拔了出来。"},"pos":"noun"}]}},"squeal":{"collins":{"senses":[{"pos":"VERB 动词","cn":"发出长而尖的叫声","en":"If someone or something squeals, they make a long, high-pitched sound.","ex":{"en":"Jennifer squealed with delight and hugged me","cn":"珍妮弗高兴地尖叫起来，然后拥抱了我。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to make a loud, high noise, or say something in a loud, high voice, because you are excited, frightened, angry, or in pain","cn":""},{"en":"to make a sudden short screaming sound or shout something because you are very frightened, excited etc","cn":""},{"en":"to make long, high unpleasant sounds or shout something in an unpleasantly loud, high voice, especially because you are angry","cn":""}]},"collocations":{"phrases":["ADJ. little | high-pitched","VERB + SQUEAL give, let out She gave a little squeal of delight. | hear","PREP. with a ~ The car stopped with a squeal of brakes. | ~ of","PHRASES the squeal of brakes, a squeal of delight • Note at SOUND"]},"media":{"uk":"media/ldoce/hwd/bre/f/squeal_n0205.mp3","us":"media/ldoce/hwd/ame/2/squeal1.mp3"},"examples":[{"en":"Children were running around squealing with excitement.","cn":"孩子们跑来跑去，兴奋地尖叫着。"},{"en":"The car squealed to a halt.","cn":"汽车嘎的一声停了下来。"}],"oxford":{"phon":"skwiːl","pos":"verb","senses":[{"en":"to make a long, high sound","cn":"尖声长叫；发出长而尖的声音","g":"[intransitive]","ex":{"en":"The pigs were squealing.","cn":"猪尖叫着。"}},{"en":"to speak in a very high voice, especially when you are excited or nervous","cn":"（尤指激动或紧张时）尖声说，高声嚷着说","g":"[transitive, intransitive]","ex":{"en":"‘Don't!’ she squealed.","cn":"“不要！”她尖叫道。"}},{"en":"to give information, especially to the police, about something illegal that somebody has done","cn":"告密；告发","g":"[intransitive]","lab":"informal, disapproving，，","ex":{"en":"Someone must have squealed on him.","cn":"肯定有人对他大喊大叫。"}},{"en":"a long high call or sound","cn":"拖长的叫声；长而尖的声音","ex":{"en":"a squeal of pain","cn":"疼痛的尖叫"},"pos":"noun"}]}},"squirrel":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"松鼠","en":"A squirrel is a small animal with a long furry tail. Squirrels live mainly in trees."},{"pos":"","cn":"","en":"相关词组：squirrel away"}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a small animal with a long furry tail that climbs trees and eats nuts","cn":"松鼠"},{"en":"to keep something in a safe place to use later","cn":"储存﹐贮藏〔供以后使用〕"}]},"vocab":{"pos":"n","senses":[{"en":"Squirrels are rodents that live in trees and have big, bushy tails. You've probably seen many squirrels in the park eating acorns and seeds."}]},"collocations":{"phrases":["ADJ. grey, red","SQUIRREL + VERB dart, scamper, scurry The squirrel scampered across the lawn"]},"media":{"img":["media/ldoce/img/squirrel.jpg"],"uk":"media/ldoce/hwd/bre/2/squirrel_v0205.mp3","us":"media/ldoce/hwd/ame/2/squirrel.mp3"},"examples":[{"en":"She had money squirrelled away in various bank accounts.","cn":"她把钱储存在几个不同的银行账户上。"},{"en":"By December I had $300 squirreled away.","cn":"到十二月份的时候﹐我已经存了300美元。"}],"oxford":{"phon":"ˈskwɪrəl","pos":"noun","senses":[{"en":"a small animal with a long, thick tail and red, grey or black fur. Squirrels eat nuts and live in trees.","cn":"松鼠"}]}},"squatter":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"擅自占住空房者","en":"A squatter is someone who lives in an unused building without having a legal right to do so and without paying any rent or any property tax."},{"pos":"N-COUNT 可数名词","cn":"擅自占用空地者","en":"A squatter is someone who occupies unused land, either to farm it or to build a house on it, without having a legal right to do so.","ex":{"en":"When they returned to Tuol Sakor, they found all the best land taken by squatters.","cn":"当回到图尔沙科尔时，他们发现那些最好的土地全都被人侵占了。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"all the people in a country or town or area, or the number of people who live in it","cn":""},{"en":"someone who lives in a particular area of a town, a particular street or building etc","cn":""},{"en":"one of the people who live in a place, especially in a town or city or in an area of a country","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/c/squatter0205.mp3","us":"media/ldoce/hwd/ame/d/squatter.mp3"},"oxford":{"phon":"ˈskwɒtə(r)","pos":"noun","senses":[{"en":"a person who is living in a building or on land without permission and without paying rent","cn":"擅自占用他人房子（或土地）的人","ex":{"en":"The squatters were evicted by bailiffs on Tuesday.","cn":"周二，占屋者被法警驱逐。"}}]}},"squally":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"伴有狂风的;刮飑的","en":"In squally weather, there are sudden strong winds which often cause brief, violent storms.","ex":{"en":"The competitors had to contend with squally weather conditions.","cn":"参赛者不得不应付狂风肆虐的天气条件。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"squally rain or snow comes with sudden strong winds","cn":"有狂风的﹐多飑的"}]},"media":{"uk":"media/ldoce/hwd/bre/c/squally0205.mp3","us":"media/ldoce/hwd/ame/3/ld41squally.mp3"},"examples":[{"en":"squally showers","cn":"狂风阵雨"}],"oxford":{"phon":"ˈskwɔːli","pos":"adjective","senses":[{"en":"involving sudden, violent and strong winds","cn":"有狂风的；刮飑的","ex":{"en":"squally showers","cn":"狂风阵雨"}}]}},"squall":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"飑;突起的大风(常引起短暂暴雨或暴雪)","en":"A squall is a sudden strong wind which often causes a brief, violent rain storm or snow storm.","ex":{"en":"The boat was hit by a squall north of the island.","cn":"船在岛的北边遇到了狂飑。"}},{"pos":"VERB 动词","cn":"嚎叫;大声啼哭","en":"If a person or animal squalls, they make a loud unpleasant noise like the noise made by a crying baby.","ex":{"en":"There was an infant squalling in the back of the church.","cn":"有个婴儿在教堂后部大声啼哭。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a sudden strong wind, especially one that brings rain or snow","cn":"飑〔突起的狂风﹐尤指夹有雨或雪〕"},{"en":"if a baby or child squalls, it cries noisily 〔","cn":"婴儿或小孩〕大声哭喊﹐号哭"}]},"vocab":{"pos":"1 v 2 n v","senses":[{"en":"A squall is a powerful, usually brief, burst of wind that usually brings rain or snow with it. When a snow squall blows across the mountain, skiers take a break in the ski lodge."}]},"media":{"uk":"media/ldoce/hwd/bre/c/squall_v0205.mp3","us":"media/ldoce/hwd/ame/8/squall1.mp3"},"examples":[{"en":"squalling kids","cn":"大声啼哭的孩子"},{"en":"snow squalls","cn":"雪飑"}],"oxford":{"phon":"skwɔːl","pos":"noun","senses":[{"en":"a sudden strong and violent wind, often with rain or snow during a storm","cn":"飑（常指暴风雨或暴风雪中突起的狂风）","ex":{"en":"A sudden vicious squall knocked her to the ground.","cn":"一场突如其来的狂风将她掀翻在地。"}},{"en":"to cry very loudly and noisily","cn":"大声啼哭；号哭","ex":{"en":"squalling kids","cn":"大声啼哭的孩子"},"pos":"verb"}]}},"squishy":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"松软的","en":"Something that is squishy is soft and easy to squash.","ex":{"en":"...squishy pink leather chairs.","cn":"松软的粉色皮椅"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"not hard, firm, or stiff, but easy to press","cn":""},{"en":"used about meat or vegetables that are soft and easy to cut, especially because they have been well cooked","cn":""},{"en":"very wet and too soft, in a way that seems unpleasant – used about bread, vegetables, and the ground","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/b/squishy0205.mp3","us":"media/ldoce/hwd/ame/9/laadsquishy.mp3"},"examples":[{"en":"squishy mud","cn":"黏糊糊的泥"}],"oxford":{"phon":"ˈskwɪʃi","pos":"adjective","senses":[{"en":"soft and wet","cn":"湿软的；黏乎乎的","ex":{"en":"The crowd pelted the speakers with squishy tomatoes.","cn":"人群向扬声器投掷软烂的西红柿。"}}]}},"squawk":{"collins":{"senses":[{"pos":"VERB 动词","cn":"(鸟)发出响亮而粗厉的叫声","en":"When a bird squawks, it makes a loud harsh noise.","ex":{"en":"I threw pebbles at the hens, and that made them jump and squawk.","cn":"我朝母鸡扔卵石，吓得它们乱跳乱叫。"}},{"pos":"VERB 动词","cn":"(人)大声抱怨，粗声抗议","en":"If a person squawks, they complain loudly, often in a high-pitched, harsh tone.","ex":{"en":"Mr Arbor squawked that the deal was a double-cross","cn":"阿伯先生大声抱怨说这笔交易是个骗局。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"if a bird squawks, it makes a loud sharp angry sound 〔","cn":"鸟〕发出响亮刺耳的怒叫声"},{"en":"to complain loudly and angrily","cn":"气愤地大声抱怨"}]},"media":{"uk":"media/ldoce/hwd/bre/5/squawk0205.mp3","us":"media/ldoce/hwd/ame/8/squawk1.mp3"},"examples":[{"en":"‘You did what?!’ she squawked. “","cn":"你干了什么？！”她惊叫道。"},{"en":"The parrot squawked and flew away.","cn":"鹦鹉尖声叫了叫飞走了。"}],"oxford":{"phon":"skwɔːk","pos":"verb","senses":[{"en":"to make a loud sharp sound","cn":"发出刺耳的尖叫声","g":"[intransitive]","ex":{"en":"The parrot squawked and flew away.","cn":"鹦鹉尖声叫了叫飞走了。"}},{"en":"to speak or make a noise in a loud, sharp voice because you are angry, surprised, etc.","cn":"尖声高叫；怒声叫嚷；吃惊地尖声说话","g":"[transitive, intransitive]","ex":{"en":"‘You did what?!’ she squawked.","cn":"“你干了什么？！”她惊叫道。"}},{"en":"a loud sharp sound made by a bird","cn":"发出刺耳的尖叫声","ex":{"en":"The bird gave a startled squawk.","cn":"小鸟受惊发出了一声刺耳的尖叫。"},"pos":"noun"},{"en":"words or sounds made in a loud, sharp voice because you are angry, surprised, etc.","cn":"尖声高叫；怒声叫嚷；吃惊地尖声说话","ex":{"en":"a squawk of protest","cn":"抗议的怒吼"},"pos":"noun"}]}},"squeaky":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"吱嘎作响的;发出刺耳声音的","en":"Something that is squeaky makes high-pitched sounds.","ex":{"en":"...squeaky floorboards","cn":"吱嘎作响的地板"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"higher than most sounds or voices","cn":""},{"en":"high and unpleasant","cn":""},{"en":"extremely high and loud, in a way that is unpleasant","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/4/squeaky0205.mp3","us":"media/ldoce/hwd/ame/6/squeaky.mp3"},"examples":[{"en":"squeaky floorboards","cn":"嘎吱作响的地板"},{"en":"a high squeaky voice","cn":"又高又尖的嗓子"}],"oxford":{"phon":"ˈskwiːki","pos":"adjective","senses":[{"en":"making a short, high sound; squeaking","cn":"发短促尖叫声的；吱吱叫的；嘎吱作响的","ex":{"en":"squeaky floorboards","cn":"嘎吱作响的地板"}}]}},"squeak":{"collins":{"senses":[{"pos":"VERB 动词","cn":"发出吱吱声;发出短促的尖叫","en":"If something or someone squeaks, they make a short, high-pitched sound.","ex":{"en":"My boots squeaked a little as I walked","cn":"我走路时靴子有点儿嘎吱嘎吱响。"}},{"pos":"VERB 动词","cn":"侥幸成功;险胜;勉强通过","en":"To squeak through or squeak by means to only just manage to get accepted, get included in something, or win something.","ex":{"en":"The President's economic package squeaked through the House of Representatives by 219 votes to 213","cn":"总统的一揽子经济计划最终以 219 票对 213 票在众议院勉强获得通过。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"if something creaks , especially something wooden such as a door, bed, or stair, it makes a long, high noise when someone puts pressure on it","cn":""},{"en":"if something squeaks , it makes a very high noise as it is moved, pushed etc, especially because two parts of it cannot rub smoothly together","cn":""},{"en":"to make a loud, long, unpleasant high sound, like the sound made by car tyres when the car stops suddenly","cn":""}]},"collocations":{"phrases":["ADJ. little | high, high-pitched","VERB + SQUEAK give, let out | hear","PREP. with a ~ The door opened with a squeak. | ~ of She gave a little squeak of surprise.","PHRASES not a squeak (figurative) &lsquo;Have you heard from them?&rsquo; &lsquo;Not a squeak since yesterday.&rsquo; | the squeak of rubber"]},"media":{"uk":"media/ldoce/hwd/bre/4/squeak_v0205.mp3","us":"media/ldoce/hwd/ame/1/squeak1.mp3"},"examples":[{"en":"We squeaked into the final with a goal in the last minute.","cn":"我们靠最后一分钟的入球侥幸进入决赛。"},{"en":"My new shoes squeak.","cn":"我的新皮鞋走路嘎吱嘎吱响。"}],"oxford":{"phon":"skwiːk","pos":"verb","senses":[{"en":"to make a short high sound that is not very loud","cn":"短促而尖厉地叫；吱吱叫；嘎吱作响","g":"[intransitive]","ex":{"en":"My new shoes squeak.","cn":"我的新鞋走路嘎吱嘎吱响。"}},{"en":"to speak in a very high voice, especially when you are nervous or excited","cn":"（尤指紧张或激动时）尖声说话","g":"[transitive, intransitive]","ex":{"en":"‘Let go of me!’ he squeaked nervously.","cn":"“放开我！”他紧张地尖叫道。"}},{"en":"to only just manage to win something, pass a test, etc.","cn":"勉强通过；侥幸成功；险胜","g":"[intransitive]","ex":{"en":"We squeaked into the final with a goal in the last minute.","cn":"我们靠最后一分钟的进球得分侥幸进入决赛。"}},{"en":"a short, high call or sound, that is not usually very loud","cn":"短促而尖厉的叫声；吱吱声","ex":{"en":"the squeak of a mouse","cn":"老鼠的吱吱叫声"},"pos":"noun"}]}},"squared":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"正方形的;带有方格图案的","en":"Something that is squared has the shape of a square, or has a pattern of squares on it.","ex":{"en":"Draw up a scale floor plan on squared paper, marking in the door opening and windows.","cn":"在方格纸上画出成比例的楼层平面图，标出门和窗的位置。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"divided into squares or marked with squares","cn":"方格的"},{"en":"the number three, nine etc multiplied by itself 3/9/10","cn":"等的平方"}]},"media":{"uk":"media/ldoce/hwd/bre/c/squared0205.mp3","us":"media/ldoce/hwd/ame/a/laadsquared.mp3"},"examples":[{"en":"squared paper","cn":"方格纸"},{"en":"Three squared equals nine. 3","cn":"的平方是9。"}],"oxford":{"phon":"skweəd","pos":"adjective","senses":[{"en":"marked with squares; divided into squares","cn":"有正方形标记的；分成正方形形状的","ex":{"en":"squared paper","cn":"方格纸"}}]},"base":"square"}});
